def _get_timezone_name(timezone):
    """Return the name of ``timezone``."""
    if timezone is None:
        return None
    if timezone == timezone.utc:
        return "UTC"
    if isinstance(timezone, datetime.timedelta):
        return timezone
    if isinstance(timezone, datetime.tzinfo):
        offset = timezone.utcoffset(None)
        if offset is None:
            return str(timezone)
        return "%+03d:%02d" % (offset.seconds // 3600, (offset.seconds % 3600) // 60)
    return str(timezone)

